const src = ($json && $json.body && typeof $json.body === 'object') ? $json.body : ($json || {});
const token = ($env.DOC_INGEST_TOKEN || '').trim();
if (!token) { throw new Error('DOC_INGEST_TOKEN is not configured'); }
const headers = ($json && $json.headers) ? $json.headers : {};
if (String(headers['x-ingest-token'] || '').trim() !== token) { throw new Error('Unauthorized'); }

const allowed = ($env.DOC_INGEST_ALLOWED_HOSTS || '').split(',').map((h) => h.trim().toLowerCase()).filter(Boolean);
if (!allowed.length) { throw new Error('DOC_INGEST_ALLOWED_HOSTS is not configured'); }

const rawUrl = String(src.file_url || '').trim();
let parsed;
try { parsed = new URL(rawUrl); } catch (e) { throw new Error('Invalid file_url'); }
if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') { throw new Error('Blocked URL scheme'); }
if (allowed.indexOf(parsed.hostname.toLowerCase()) === -1) { throw new Error('Host not allowed: ' + parsed.hostname); }
const blocked = /^(localhost|127\.|0\.0\.0\.0|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.|\[?::1\]?)/i;
if (blocked.test(parsed.hostname)) { throw new Error('Private address blocked'); }

const rawName = String(src.filename || '').trim();
const base = rawName.split(/[\\/]/).pop().replace(/[^A-Za-z0-9._-]/g, '_').replace(/^\.+/, '');
if (!base || base.length > 128) { throw new Error('Invalid filename'); }
if (!/\.(pdf|docx?|xlsx?|pptx?|txt|md|csv|json)$/i.test(base)) { throw new Error('File extension not allowed'); }

const dir = 'uploads/' + Date.now() + '-' + Math.random().toString(36).slice(2, 10);
return [{ json: Object.assign({}, src, { file_url: parsed.toString(), filename: base, file_path: dir + '/' + base }) }];
